16	// bs is one backslash. The manifests below build their escape text out of
17	// it, so escCJK below is the twelve ASCII characters of two JSON unicode
18	// escapes (backslash, u, 6, 2, 7, 9, backslash, u, 6, b, 2, 1) — the JSON
19	// parser is what decodes them into the two CJK characters.
20	const bs = "\\"
21	
22	var (
23		// escCJK spells 批次-1 with both CJK characters escaped.
24		escCJK = bs + "u6279" + bs + "u6b21" + "-1"
25		// escMixed spells 批次-1 with 批 written directly and 次 escaped.
26		escMixed = "批" + bs + "u6b21" + "-1"
27		// escNew spells 批次-新 fully escaped.
28		escNew = bs + "u6279" + bs + "u6b21" + "-" + bs + "u65b0"
29		// esc10000 and esc10FFFF are the surrogate-pair spellings of the two
30		// boundary characters a UTF-16 pair can express.
31		esc10000  = bs + "ud800" + bs + "udc00" // U+10000
32		esc10FFFF = bs + "udbff" + bs + "udfff" // U+10FFFF
33		// escEmoji spells 😀 (U+1F600) as a surrogate pair; escEmojiMixedHex
34		// is the same pair with the hex letter case varied.
35		escEmoji         = bs + "ud83d" + bs + "ude00"
36		escEmojiMixedHex = bs + "uD83d" + bs + "uDE00"
37		// escFFFD spells a genuine U+FFFD replacement character as an escape.
38		escFFFD = bs + "ufffd"
