1	package batchreg
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// This file is the regression net for a registry reached through a DIRECTORY
14	// symbolic link followed by "..". With work/alias -> store/child, the user
15	// path work/alias/../batches.json names store/batches.json: the ".." leaves
16	// the directory the link really points at, not the directory holding the
17	// link. A save resolved lexically collapses alias/.. to work and writes next
18	// to the link; the rule under guard is that read and save resolve the path
19	// the same physical way the kernel does, so the new record lands in the real
20	// file, nothing is created next to the link (write access there is not even
21	// required), and an unrelated same-named file beside the link is untouched.
22	
23	// dirLinkFixtureAt builds, under root,
24	//
25	//	root/
26	//	  store/
27	//	    child/                 (real directory)
28	//	    batches.json           (the real registry with one OLD-1 record)
29	//	  work/
30	//	    alias -> linkTarget    (directory link into store)
31	//	    batches.json           (an unrelated decoy registry)
32	//
33	// linkTarget is the exact text stored in the link. It returns the registry
34	// path a user would type (work/alias/../batches.json, built WITHOUT lexical
35	// cleaning so the link segment and the ".." both survive), the real registry
36	// path, the decoy path and the original real-registry bytes.
37	func dirLinkFixtureAt(t *testing.T, root, linkTarget string) (userPath, realPath, decoyPath, aliasPath string, original []byte) {
38		t.Helper()
39		storeDir := filepath.Join(root, "store")
40		childDir := filepath.Join(storeDir, "child")
41		if err := os.MkdirAll(childDir, 0o755); err != nil {
42			t.Fatal(err)
43		}
44		workDir := filepath.Join(root, "work")
45		if err := os.MkdirAll(workDir, 0o755); err != nil {
46			t.Fatal(err)
47		}
48		realPath = filepath.Join(storeDir, "batches.json")
49		writeRegistry(t, realPath, symlinkFixtureRegistry)
50		decoyPath = filepath.Join(workDir, "batches.json")
51		writeRegistry(t, decoyPath, `{"version":1,"batches":[{"batch":"DECOY","product":"P-0","quantity":1,"unit":"m"}]}`)
52		aliasPath = filepath.Join(workDir, "alias")
53		if err := os.Symlink(linkTarget, aliasPath); err != nil {
54			t.Fatal(err)
55		}
56		// String concatenation on purpose: filepath.Join/Clean would collapse
57		// "alias/.." to "work" and erase exactly the path shape under test.
58		userPath = aliasPath + string(os.PathSeparator) + ".." + string(os.PathSeparator) + "batches.json"
59		original, err := os.ReadFile(realPath)
60		if err != nil {
61			t.Fatal(err)
62		}
63		return userPath, realPath, decoyPath, aliasPath, original
64	}
65	
66	// dirLinkFixture builds the layout in a fresh temporary directory.
67	func dirLinkFixture(t *testing.T, linkTarget string) (root, userPath, realPath, decoyPath, aliasPath string, original []byte) {
68		t.Helper()
69		root = t.TempDir()
70		userPath, realPath, decoyPath, aliasPath, original = dirLinkFixtureAt(t, root, linkTarget)
71		return root, userPath, realPath, decoyPath, aliasPath, original
72	}
73	
74	// pinFile stamps a past mtime on path so any rewrite is observable.
75	func pinFile(t *testing.T, path string) time.Time {
76		t.Helper()
77		pinned := time.Date(2008, time.August, 9, 10, 11, 12, 0, time.UTC)
78		if err := os.Chtimes(path, pinned, pinned); err != nil {
79			t.Fatal(err)
80		}
81		return pinned
82	}
83	
84	// Reading the registry through work/alias/../batches.json sees the real
85	// store/batches.json, and a save of a newly registered batch appends to that
86	// real file: old record first, new record last, visible through the user path
87	// and the real path alike. The decoy beside the link keeps its bytes, the
88	// link keeps its target text, and no temporary file survives anywhere.
89	func TestSaveThroughDirectorySymlinkDotDotLandsInRealFile(t *testing.T) {
90		cases := []struct {
91			name   string
92			target func(root string) string
93		}{
94			{"relative target", func(root string) string { return filepath.Join("..", "store", "child") }},
95			{"absolute target", func(root string) string { return filepath.Join(root, "store", "child") }},
96		}
97		for _, tc := range cases {
98			t.Run(tc.name, func(t *testing.T) {
99				root := t.TempDir()
100				userPath, realPath, decoyPath, aliasPath, original := dirLinkFixtureAt(t, root, tc.target(root))
101	
102				decoyBytes, err := os.ReadFile(decoyPath)
103				if err != nil {
104					t.Fatal(err)
105				}
106				realPinned := pinFile(t, realPath)
107				decoyPinned := pinFile(t, decoyPath)
108	
109				reg, existed, err := Load(userPath)
110				if err != nil || !existed {
111					t.Fatalf("reading through the directory link must load the real registry: existed=%v err=%v", existed, err)
112				}
113				if len(reg.Batches) != 1 || reg.Batches[0].Batch != "OLD-1" {
114					t.Fatalf("the user path must see the real records, got %+v", reg.Batches)
115				}
116				if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
117					t.Fatal(err)
118				}
119				if err := Save(userPath, reg); err != nil {
120					t.Fatalf("saving through the directory link must succeed: %v", err)
121				}
122	
123				want := []Batch{
124					saveBatch("OLD-1", "P-1", 10, "kg"),
125					saveBatch("NEW-1", "P-9", 5, "box"),
126				}
127				assertBatchesEqual(t, mustLoad(t, realPath).Batches, want)
128				assertBatchesEqual(t, mustLoad(t, userPath).Batches, want)
129	
130				// The real file is the one rewritten: its pinned mtime must move.
131				if info, err := os.Stat(realPath); err != nil {
132					t.Fatal(err)
133				} else if info.ModTime().Equal(realPinned) {
134					t.Fatal("the real registry was not rewritten; the save landed elsewhere")
135				}
136				// The decoy beside the link is unrelated: bytes and mtime intact.
137				after, err := os.ReadFile(decoyPath)
138				if err != nil {
139					t.Fatal(err)
140				}
141				if !bytes.Equal(after, decoyBytes) {
142					t.Fatalf("the decoy beside the link changed:\nbefore %s\nafter  %s", decoyBytes, after)
143				}
144				if info, err := os.Stat(decoyPath); err != nil {
145					t.Fatal(err)
146				} else if !info.ModTime().Equal(decoyPinned) {
147					t.Fatalf("the decoy mtime moved: got %v want %v", info.ModTime(), decoyPinned)
148				}
149				// Nothing was written next to the link: only the link and the
150				// decoy may exist there.
151				entries, err := os.ReadDir(filepath.Dir(aliasPath))
152				if err != nil {
153					t.Fatal(err)
154				}
155				for _, e := range entries {
156					if e.Name() != "alias" && e.Name() != "batches.json" {
157						t.Fatalf("save created %q next to the directory link", e.Name())
158					}
159				}
160				assertLinkIntact(t, aliasPath, tc.target(root))
161				assertNoLeftoverTempFiles(t, root)
162				_ = original
163			})
164		}
165	}
166	
167	// mustLoad loads path or fails the test; it keeps the fixtures readable.
168	func mustLoad(t *testing.T, path string) *Registry {
169		t.Helper()
170		reg, existed, err := Load(path)
171		if err != nil || !existed {
172			t.Fatalf("Load(%q): existed=%v err=%v", path, existed, err)
173		}
174		return reg
175	}
176	
177	// A save through work/alias/../batches.json must not require write access in
178	// work: making the link's own directory read-and-execute-only leaves the save
179	// working, because the temporary file is prepared in the real target
180	// directory. Skipped under root, which bypasses directory permission bits.
181	func TestSaveThroughDirectorySymlinkDotDotNeedsNoWriteInLinkDirectory(t *testing.T) {
182		if os.Geteuid() == 0 {
183			t.Skip("root bypasses directory write permission bits")
184		}
185		root, userPath, realPath, decoyPath, aliasPath, _ := dirLinkFixture(t, filepath.Join("..", "store", "child"))
186		workDir := filepath.Dir(aliasPath)
187		if err := os.Chmod(workDir, 0o555); err != nil {
188			t.Fatal(err)
189		}
190		t.Cleanup(func() { _ = os.Chmod(workDir, 0o755) })
191	
192		reg := mustLoad(t, userPath)
193		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
194			t.Fatal(err)
195		}
196		if err := Save(userPath, reg); err != nil {
197			t.Fatalf("a read-only link directory must not block the save: %v", err)
198		}
199		assertBatchesEqual(t, mustLoad(t, realPath).Batches, []Batch{
200			saveBatch("OLD-1", "P-1", 10, "kg"),
201			saveBatch("NEW-1", "P-9", 5, "box"),
202		})
203		assertBatchesEqual(t, mustLoad(t, userPath).Batches, mustLoad(t, realPath).Batches)
204		assertLinkIntact(t, aliasPath, filepath.Join("..", "store", "child"))
205		assertNoLeftoverTempFiles(t, root)
206		// The read-only directory must contain only what it started with.
207		entries, err := os.ReadDir(workDir)
208		if err != nil {
209			t.Fatal(err)
210		}
211		for _, e := range entries {
212			if e.Name() != "alias" && e.Name() != "batches.json" {
213				t.Fatalf("save created %q in the read-only link directory", e.Name())
214			}
215		}
216		_ = decoyPath
217	}
218	
219	// The atomic rename — the step that actually chooses which file is replaced —
220	// must target the real store/batches.json, never the same-named decoy beside
221	// the link. This works under every account, root included, because it
222	// observes Save's own resolved target.
223	func TestSaveThroughDirectorySymlinkDotDotRenamesRealFile(t *testing.T) {
224		root, userPath, realPath, decoyPath, aliasPath, original := dirLinkFixture(t, filepath.Join("..", "store", "child"))
225		pinned := pinFile(t, realPath)
226		decoyBytes, err := os.ReadFile(decoyPath)
227		if err != nil {
228			t.Fatal(err)
229		}
230	
231		cause := errors.New("injected replacement refusal through directory link")
232		var renamedTo string
233		old := RenameTempFile
234		RenameTempFile = func(oldpath, newpath string) error {
235			renamedTo = newpath
236			return cause
237		}
238		t.Cleanup(func() { RenameTempFile = old })
239	
240		reg := mustLoad(t, userPath)
241		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
242			t.Fatal(err)
243		}
244		err = Save(userPath, reg)
245		if err == nil {
246			t.Fatal("Save must surface the injected rename failure")
247		}
248		if !errors.Is(err, cause) {
249			t.Errorf("error %v must carry the cause %v", err, cause)
250		}
251		if !strings.Contains(err.Error(), userPath) {
252			t.Errorf("error %q must name the user-supplied path %q", err.Error(), userPath)
253		}
254		if renamedTo != realPath {
255			t.Fatalf("rename target = %q, want the real registry %q", renamedTo, realPath)
256		}
257		if renamedTo == decoyPath {
258			t.Fatal("the save must never rename onto the decoy beside the link")
259		}
260	
261		// Failed save: real registry keeps bytes and mtime, decoy untouched, no
262		// temporary file survives, the link is unchanged.
263		if info, err := os.Stat(realPath); err != nil {
264			t.Fatal(err)
265		} else if !info.ModTime().Equal(pinned) {
266			t.Fatalf("failed save moved the real registry mtime: got %v want %v", info.ModTime(), pinned)
267		}
268		after, err := os.ReadFile(realPath)
269		if err != nil {
270			t.Fatal(err)
271		}
272		if !bytes.Equal(after, original) {
