17	)
18	
19	// End-to-end regression for batch-register's promise that a success output is
20	// printed only after the new record is completely saved: the batch submitted
21	// here is legal under every flag rule and its id is not registered yet, so a
22	// failure can only originate from the save itself — never from invalid input,
23	// a batch conflict, a corrupt registry or an unreadable path.
24	//
25	// Two real save failures are injected deterministically through batchreg's
26	// step hooks (no disk exhaustion, no filesystem fault, no special account):
27	//
28	//   - the new content write stops while the new table is incomplete;
29	//   - the new table is fully prepared in the temporary file but replacing the
30	//     registry file is refused.
31	//
32	// Each is run against an existing multi-batch registry — written in a layout
33	// distinct from Save's own output — and against a path where no registry
34	// exists yet. Whatever step fails, batch-register must report failure to its
35	// caller: non-zero exit code, stderr naming the user-supplied registry path
36	// and the concrete save reason (never worded as an input error), empty
37	// stdout, the existing registry kept byte-for-byte and timestamp-for-
38	// timestamp with its records, fields and order intact and still readable (a
39	// failure must not reformat the file to "restore" it), or the missing target
40	// still absent — no half-written registry and no leftover temporary file in
41	// either case. Success controls with the very same request prove it registers
42	// normally: exit code zero, one JSON object carrying the normalized four
43	// fields plus status "created", old records keeping their order and the new
44	// batch appended last, or a readable registry created when none existed.
45	//
46	// The failure scenarios run in a real child process — the test binary
47	// re-invoked with -wrap.batch-register — so the assertions cover the actual
48	// process contract (exit code, stdout, stderr) rather than an in-process
49	// error return, while staying fully offline: the child is this same binary.
50	
51	var wrapBatchRegister = flag.Bool("wrap.batch-register", false, "internal: run one batch-register invocation and exit")
52	
53	// runWrappedBatchRegister performs exactly one batch-register against the
54	// registry named in WRAP_REGISTRY with the record from WRAP_BATCH /
55	// WRAP_PRODUCT / WRAP_QUANTITY / WRAP_UNIT, optionally failing one save step
56	// as selected by WRAP_FAULT. Exit codes mimic the real command: 1 for a
57	// reported batch-register failure (message written to stderr like main does,
58	// usage text included for input errors), 3 for a harness problem inside the
59	// child, 0 for success.
60	func runWrappedBatchRegister() int {
61		registry := os.Getenv("WRAP_REGISTRY")
62		reason := os.Getenv("WRAP_REASON")
63		// harnessExit reports a broken test harness from inside an injected hook,
64		// whose signature allows only an error; the parent treats code 3 as a
65		// harness failure rather than a command failure.
66		harnessExit := func(format string, args ...any) error {
67			fmt.Fprintf(os.Stderr, "wrap harness: "+format+"\n", args...)
68			os.Exit(3)
69			return nil
70		}
71		switch saveFault(os.Getenv("WRAP_FAULT")) {
72		case faultWrite:
73			// Part of the new content genuinely reaches the temporary file, then
74			// the write stops with the new table incomplete.
75			batchreg.WriteTempContent = func(f *os.File, data []byte) (int, error) {
76				half := len(data) / 2
77				if _, err := f.Write(data[:half]); err != nil {
78					fmt.Fprintf(os.Stderr, "wrap harness: setup write failed: %v\n", err)
79					os.Exit(3)
80				}
81				return half, errors.New(reason)
82			}
83		case faultRename:
84			// The complete new table must be ready before the replacement is
85			// refused; markers are checked on the prepared temporary file.
86			markers := strings.Split(os.Getenv("WRAP_MARKERS"), ",")
87			batchreg.RenameTempFile = func(oldpath, newpath string) error {
88				if newpath != registry {
89					return harnessExit("rename must target %q, got %q", registry, newpath)
90				}
91				prepared, err := os.ReadFile(oldpath)
92				if err != nil {
93					return harnessExit("prepared temporary file is unreadable: %v", err)
94				}
95				for _, marker := range markers {
96					if !bytes.Contains(prepared, []byte(marker)) {
97						return harnessExit("prepared content is missing %q: %s", marker, prepared)
98					}
99				}
100				return errors.New(reason)
101			}
102		case faultNone:
103		default:
104			fmt.Fprintf(os.Stderr, "wrap harness: unknown fault %q\n", os.Getenv("WRAP_FAULT"))
105			return 3
106		}
107		args := []string{
108			"--registry", registry,
109			"--batch", os.Getenv("WRAP_BATCH"),
110			"--product", os.Getenv("WRAP_PRODUCT"),
111			"--quantity", os.Getenv("WRAP_QUANTITY"),
112			"--unit", os.Getenv("WRAP_UNIT"),
113		}
114		if err := runBatchRegister(args, os.Stdout); err != nil {
115			fmt.Fprintln(os.Stderr, "govflow:", err)
116			var ue *usageError
117			if errors.As(err, &ue) {
118				fmt.Fprint(os.Stderr, ue.usage)
119			}
120			return 1
121		}
122		return 0
123	}
124	
125	// The one legal registration request every scenario in this file submits:
126	// a batch id nothing registers, padded text and leading zeros that
127	// normalization removes, and CJK/emoji text that must survive verbatim.
128	const (
129		registerFailureBatchFlag    = " B-NEW-1 "
130		registerFailureProductFlag  = "新产品😀"
131		registerFailureQuantityFlag = "00042"
132		registerFailureUnitFlag     = " 千克 "
133	)
134	
135	// registerFailureRegistryJSON is the multi-batch registry every
136	// existing-target scenario starts from, in a legal layout Save would never
137	// produce: compact, members out of order, no trailing newline. A failed save
138	// must not reformat it.
139	const registerFailureRegistryJSON = `{"batches":[` +
140		`{"unit":"kg","quantity":7,"product":"P-1","batch":"B-OLD-1"},` +
141		`{"batch":"B-OLD-2","product":"苹果","quantity":80,"unit":"箱"},` +
142		`{"batch":"B-OLD-3","product":"P-3","quantity":9223372036854775807,"unit":"m"}],"version":1}`
143	
144	// registerFailurePinnedModTime is pinned onto the existing registry so any
145	// rewrite — even one restoring identical bytes — is observable.
146	var registerFailurePinnedModTime = time.Date(2013, time.July, 19, 8, 9, 10, 0, time.UTC)
147	
148	// registerFailureOriginalBatches is what the fixture registry holds, in
149	// stored order; a failed save must preserve exactly these records.
150	var registerFailureOriginalBatches = []registerResult{
151		{Batch: "B-OLD-1", Product: "P-1", Quantity: 7, Unit: "kg"},
152		{Batch: "B-OLD-2", Product: "苹果", Quantity: 80, Unit: "箱"},
153		{Batch: "B-OLD-3", Product: "P-3", Quantity: 9223372036854775807, Unit: "m"},
154	}
155	
156	// runRegisterChild re-executes the test binary in wrapped one-command mode
157	// with the chosen fault and returns the child's exit code plus captured
158	// output. existingRegistry says whether the target file pre-exists, which
159	// decides which batch ids the fully prepared new table must contain.
160	func runRegisterChild(t *testing.T, registry string, fault saveFault, reason string, existingRegistry bool) (code int, stdout, stderr []byte) {
161		t.Helper()
162		exe, err := os.Executable()
163		if err != nil {
164			t.Fatal(err)
165		}
166		// The new batch must be present in the prepared temporary file before the
167		// replacement is refused, alongside every batch already stored.
168		markers := []string{"B-NEW-1", "新产品😀", "千克"}
169		if existingRegistry {
170			markers = append(markers, "B-OLD-1", "B-OLD-2", "B-OLD-3", "苹果")
171		}
172		cmd := exec.Command(exe, "-wrap.batch-register")
173		cmd.Env = append(os.Environ(),
174			"WRAP_REGISTRY="+registry,
175			"WRAP_BATCH="+registerFailureBatchFlag,
176			"WRAP_PRODUCT="+registerFailureProductFlag,
177			"WRAP_QUANTITY="+registerFailureQuantityFlag,
178			"WRAP_UNIT="+registerFailureUnitFlag,
179			"WRAP_FAULT="+string(fault),
180			"WRAP_REASON="+reason,
181			"WRAP_MARKERS="+strings.Join(markers, ","),
182		)
183		var outBuf, errBuf bytes.Buffer
184		cmd.Stdout = &outBuf
185		cmd.Stderr = &errBuf
186		runErr := cmd.Run()
187		stdout = outBuf.Bytes()
188		stderr = errBuf.Bytes()
189		if runErr == nil {
190			return 0, stdout, stderr
191		}
192		var exitErr *exec.ExitError
193		if errors.As(runErr, &exitErr) {
194			return exitErr.ExitCode(), stdout, stderr
195		}
196		t.Fatalf("child process did not start: %v", runErr)
197		return 0, nil, nil
198	}
199	
200	// TestBatchRegisterCLISaveFailuresLeaveNoTrace runs both injected save
201	// failures against both target states. The request is the shared legal one;
202	// the failure must be reported as a save failure and leave the world exactly
203	// as it was before the command.
204	func TestBatchRegisterCLISaveFailuresLeaveNoTrace(t *testing.T) {
205		causes := map[saveFault]string{
206			faultWrite:  "injected save failure: new registry content not fully written",
207			faultRename: "injected save failure: complete new registry cannot replace the target",
208		}
209		for _, fault := range []saveFault{faultWrite, faultRename} {
210			for _, target := range []string{"existing registry", "missing registry"} {
211				name := string(fault) + "/" + strings.ReplaceAll(target, " ", "_")
212				t.Run(name, func(t *testing.T) {
213					dir := t.TempDir()
214					registry := filepath.Join(dir, "reg.json")
215					existing := target == "existing registry"
216					var originalBytes []byte
217					if existing {
218						writeFile(t, registry, registerFailureRegistryJSON)
219						if err := os.Chtimes(registry, registerFailurePinnedModTime, registerFailurePinnedModTime); err != nil {
220							t.Fatal(err)
221						}
222						originalBytes = readFileSnapshot(t, registry)
223					}
224	
225					code, stdout, stderr := runRegisterChild(t, registry, fault, causes[fault], existing)
226	
227					// The caller must observe a command failure, not a success.
228					if code != 1 {
229						t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
230					}
231					if len(bytes.TrimSpace(stdout)) != 0 {
232						t.Fatalf("stdout must stay empty on save failure, got %q", stdout)
233					}
234					msg := string(stderr)
235					// stderr must identify the command, the user-supplied registry
236					// path and the concrete save reason.
237					for _, want := range []string{
238						"govflow:",
239						"cannot save registry",
240						registry,
241						causes[fault],
242					} {
243						if !strings.Contains(msg, want) {
244							t.Fatalf("stderr must contain %q:\n%s", want, msg)
245						}
246					}
247					// The request is legal and conflict-free (proven by the success
248					// controls below); the failure wording must never masquerade as
249					// invalid input or a batch conflict.
250					for _, mustNot := range []string{
251						"usage:", "missing required flag", "invalid --",
252						"already registered", "conflicting field",
253					} {
254						if strings.Contains(msg, mustNot) {
255							t.Fatalf("a save failure must not be reported as %q:\n%s", mustNot, msg)
256						}
257					}
258	
259					if existing {
260						// The existing registry survives with exact bytes and
261						// modification time — no reformatting to "restore" it — and
262						// still loads with its original records, fields and order.
263						info, err := os.Stat(registry)
264						if err != nil {
265							t.Fatalf("the original registry must still exist: %v", err)
266						}
267						if !info.ModTime().Equal(registerFailurePinnedModTime) {
268							t.Fatalf("failed registration changed the registry mtime: got %v, want %v",
269								info.ModTime(), registerFailurePinnedModTime)
270						}
271						after := readFileSnapshot(t, registry)
272						if !bytes.Equal(after, originalBytes) {
273							t.Fatalf("failed registration changed the registry bytes:\nbefore: %s\nafter:  %s", originalBytes, after)
274						}
275						if bytes.Contains(after, []byte("B-NEW-1")) {
276							t.Fatalf("the new batch landed in the registry: %s", after)
277						}
278						stored := readStoredBatches(t, registry)
279						if len(stored) != len(registerFailureOriginalBatches) {
280							t.Fatalf("registry must keep exactly its original batches, got %+v", stored)
281						}
282						for i, want := range registerFailureOriginalBatches {
283							got := stored[i]
284							got.Status = ""
285							if got != want {
286								t.Fatalf("original record %d = %+v, want %+v", i+1, got, want)
287							}
288						}
289					} else {
290						// With no prior registry there must still be no file: not
291						// an empty registry, not a half-written record.
292						if _, err := os.Stat(registry); !os.IsNotExist(err) {
293							t.Fatalf("failed registration must not create the registry, stat err=%v", err)
294						}
295					}
296					assertNoSaveLeftovers(t, dir, filepath.Base(registry))
297				})
298			}
299		}
300	}
301	
302	// The success control against an existing registry: with the save healthy the
303	// very request that failed above registers. Stdout is exactly one JSON object
304	// carrying the normalized four fields plus status "created", the old records
305	// keep their order and the new batch is appended last.
306	func TestBatchRegisterCLISaveSuccessAgainstExistingRegistry(t *testing.T) {
307		dir := t.TempDir()
308		registry := filepath.Join(dir, "reg.json")
309		writeFile(t, registry, registerFailureRegistryJSON)
310		if err := os.Chtimes(registry, registerFailurePinnedModTime, registerFailurePinnedModTime); err != nil {
311			t.Fatal(err)
312		}
313	
314		stdout, err := registerCLI(t, registry,
315			registerFailureBatchFlag, registerFailureProductFlag,
316			registerFailureQuantityFlag, registerFailureUnitFlag)
317		if err != nil {
318			t.Fatalf("the legal request must register when the save does not fail: %v", err)
319		}
320	
321		created := decodeRegisterResult(t, stdout)
322		want := registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克", Status: "created"}
323		if created != want {
324			t.Fatalf("registration result = %+v, want %+v", created, want)
325		}
326	
327		// A real save must have happened, observable as a new mtime rather than
328		// the pinned one, and the new record agrees field by field with what the
329		// registry finally holds, appended after the untouched originals.
330		info, err := os.Stat(registry)
331		if err != nil {
332			t.Fatal(err)
333		}
334		if info.ModTime().Equal(registerFailurePinnedModTime) {
335			t.Fatal("a creating registration must replace the file; the pinned mtime survived")
336		}
337		stored := readStoredBatches(t, registry)
338		wantStored := append(append([]registerResult(nil), registerFailureOriginalBatches...),
339			registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克"})
340		if len(stored) != len(wantStored) {
341			t.Fatalf("registry holds %d records, want %d: %+v", len(stored), len(wantStored), stored)
342		}
343		for i, w := range wantStored {
344			got := stored[i]
345			got.Status = ""
346			if got != w {
347				t.Fatalf("stored record %d = %+v, want %+v", i+1, got, w)
348			}
349		}
350		assertNoSaveLeftovers(t, dir, filepath.Base(registry))
351	}
352	
353	// The success control with no prior registry: the file is created, readable,
354	// and holds exactly the one new batch.
355	func TestBatchRegisterCLISaveSuccessWithMissingRegistry(t *testing.T) {
356		dir := t.TempDir()
357		registry := filepath.Join(dir, "reg.json")
358	
359		stdout, err := registerCLI(t, registry,
360			registerFailureBatchFlag, registerFailureProductFlag,
361			registerFailureQuantityFlag, registerFailureUnitFlag)
362		if err != nil {
363			t.Fatalf("the legal request must register and create the registry: %v", err)
364		}
365	
366		created := decodeRegisterResult(t, stdout)
367		want := registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克", Status: "created"}
368		if created != want {
369			t.Fatalf("registration result = %+v, want %+v", created, want)
370		}
371	
372		stored := readStoredBatches(t, registry)
373		if len(stored) != 1 {
374			t.Fatalf("created registry holds %d records, want 1: %+v", len(stored), stored)
375		}
376		got := stored[0]
377		got.Status = ""
378		if got != (registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克"}) {
379			t.Fatalf("stored record = %+v, want the registered batch", got)
380		}
381		assertNoSaveLeftovers(t, dir, filepath.Base(registry))
382	}
383	
384	// The save-failure path must surface the quoted target path verbatim; this
385	// guards the wording the failure scenarios assert on, in a direct check that
386	// reads naturally when it breaks.
387	func TestBatchRegisterCLISaveFailureWordingNamesPath(t *testing.T) {
388		dir := t.TempDir()
389		registry := filepath.Join(dir, "reg.json")
390		writeFile(t, registry, registerFailureRegistryJSON)
391	
392		code, stdout, stderr := runRegisterChild(t, registry, faultRename, "injected replacement refusal", true)
393		if code != 1 {
394			t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
395		}
396		if len(stdout) != 0 {
397			t.Fatalf("stdout must be empty, got %q", stdout)
398		}
399		want := "cannot save registry " + strconv.Quote(registry) + ": injected replacement refusal"
400		if !strings.Contains(string(stderr), want) {
401			t.Fatalf("stderr must contain %q:\n%s", want, stderr)
402		}
403	}
